//! Raw SSE projection: lifecycle evidence only, never candidate semantic scores.
use crate::{Result,canonical::{digest,sha256}};
use serde_json::{Value,json};
use std::collections::{BTreeMap,BTreeSet};
pub const TERMINALS:[&str;4]=["run_finished","run_error","run_cancelled","run_blocked"];
const TEXT:[&str;2]=["text_delta","text_message_content"];
const START:[&str;2]=["tool_call_start","tool_call_started"];
const RESULT:[&str;3]=["tool_call_result","tool_call_completed","tool_result"];
pub fn redact_text(s:&str)->String{let mut s=s.to_owned();for pattern in [r"\bsk-[A-Za-z0-9_-]{12,}\b",r"(?i)\bbearer\s+[A-Za-z0-9._~+/=-]{12,}",r#"(?i)\b(?:api[_ -]?key|access[_ -]?token|password|secret)\s*[:=]\s*['"]?[A-Za-z0-9._~+/=-]{8,}"#]{s=regex::Regex::new(pattern).unwrap().replace_all(&s,"[REDACTED]").into_owned();}s}
pub(crate) fn redact(v:&Value)->Value{match v{Value::String(s)=>json!(redact_text(s)),Value::Array(a)=>json!(a.iter().map(redact).collect::<Vec<_>>()),Value::Object(m)=>Value::Object(m.iter().map(|(k,v)|(k.clone(),redact(v))).collect()),_=>v.clone()}}
fn whitelist(v:&Value,fields:&[&str])->Value{let mut out=json!({});for f in fields{if let Some(v)=v.get(*f){out[*f]=redact(v)}}out}
pub fn summarize(events:&[Value],stream_hash:&str)->Value{
 let(mut starts,mut finishes,mut tools,mut results,mut terminals,mut texts,mut sequence)=(vec![],vec![],vec![],vec![],vec![],vec![],vec![]);let mut counts=BTreeMap::<String,usize>::new();let mut attempts=BTreeSet::new();let mut output=String::new();
 for (ordinal,event) in events.iter().enumerate(){let kind=event["event_type"].as_str().unwrap_or("");let data=&event["data"];*counts.entry(kind.into()).or_default()+=1;
 if TEXT.contains(&kind){let text=data.as_str().or_else(||["content","message","delta"].into_iter().find_map(|k|data[k].as_str())).unwrap_or("");output.push_str(text);texts.push(json!({"ordinal":ordinal,"event_type":kind,"content_sha256":sha256(text.as_bytes()),"content_chars":text.chars().count()}));}
 if let Some(id)=data["attempt_id"].as_str().filter(|s|!s.is_empty()){attempts.insert(id.to_owned());}
 let fields:&[&str]=if kind=="subagent_started"{&["agent_id","agent_type","profile_id","source_plugin","definition_sha256","dispatch_index","attempt_id","started_monotonic_ms"]}else if kind=="subagent_finished"{&["agent_id","agent_type","profile_id","source_plugin","definition_sha256","dispatch_index","attempt_id","status","started_monotonic_ms","finished_monotonic_ms","duration_ms","tool_calls","result_summary","error"]}else if START.contains(&kind){&["tool_call_id","call_id","tool_id","name","tool_name","attempt_id","arguments"]}else if RESULT.contains(&kind){&["tool_call_id","call_id","tool_id","name","tool_name","attempt_id","success","status","error","error_code","side_effect_state","result","result_preview"]}else if TERMINALS.contains(&kind){&["attempt_id","run_id","status","error","error_code","duration_ms"]}else{&[]};
 if !fields.is_empty(){let mut receipt=whitelist(data,fields);receipt["ordinal"]=json!(ordinal);if START.contains(&kind)||RESULT.contains(&kind)||TERMINALS.contains(&kind){receipt["event_type"]=json!(kind)}if TERMINALS.contains(&kind)&&data["metadata"]["terminal_envelope"].is_object(){receipt["terminal_envelope"]=whitelist(&data["metadata"]["terminal_envelope"],&["attempt_id","run_id","tenant_id","status"])}match kind{"subagent_started"=>starts.push(receipt),"subagent_finished"=>finishes.push(receipt),_ if START.contains(&kind)=>tools.push(receipt),_ if RESULT.contains(&kind)=>results.push(receipt),_=>terminals.push(receipt)}}
 if TEXT.contains(&kind)||!fields.is_empty(){sequence.push(json!({"ordinal":ordinal,"event_type":kind}));}
 }
 let by_agent=starts.iter().filter_map(|v|v["agent_id"].as_str().filter(|s|!s.is_empty()).map(|id|(id,v))).collect::<BTreeMap<_,_>>();for finish in &mut finishes{if let Some(start)=finish["agent_id"].as_str().and_then(|id|by_agent.get(id)){for field in ["agent_type","profile_id","source_plugin","definition_sha256"]{if finish.get(field).is_none(){if let Some(v)=start.get(field){finish[field]=v.clone()}}}}}
 let by_index=finishes.iter().filter_map(|v|v["dispatch_index"].as_i64().map(|id|(id,v))).collect::<BTreeMap<_,_>>();let mut overlaps=vec![];for (li,left) in &by_index{for (ri,right) in by_index.range((std::ops::Bound::Excluded(*li),std::ops::Bound::Unbounded)){let values=[left["started_monotonic_ms"].as_f64(),left["finished_monotonic_ms"].as_f64(),right["started_monotonic_ms"].as_f64(),right["finished_monotonic_ms"].as_f64()];let overlap=if values.iter().all(Option::is_some){(values[1].unwrap().min(values[3].unwrap())-values[0].unwrap().max(values[2].unwrap())).max(0.)}else{0.};overlaps.push(json!({"left_dispatch_index":li,"right_dispatch_index":ri,"observed":overlap>0.,"overlap_ms":overlap}));}}
 let output=redact_text(output.trim()).chars().take(100000).collect::<String>();json!({"event_counts":counts,"stream_sha256":stream_hash,"attempt_ids":attempts,"candidate_output":output,"candidate_output_sha256":sha256(output.as_bytes()),"text_events":texts,"event_sequence":sequence,"subagent_starts":starts,"subagent_finishes":finishes,"parallel_overlaps":overlaps,"tool_starts":tools,"tool_results":results,"terminal_events":terminals})
}
pub fn attestation(payload:&Value,key:&str)->Result<Value>{if key.len()<32{return Err("collector key requires at least 32 bytes".into())}Ok(json!({"algorithm":"hmac-sha256","key_id":&sha256(key.as_bytes())[..24],"digest":crate::seals::hmac_hex(payload,key)?}))}
pub fn verify_attestation(document:&Value,key:&str)->Result<()>{let mut payload=document.clone();let signature=payload.as_object_mut().ok_or("document must be object")?.remove("collector_attestation").ok_or("collector attestation missing")?;let expected=attestation(&payload,key)?;for field in ["algorithm","key_id","digest"]{if !crate::seals::constant_eq(signature[field].as_str().unwrap_or(""),expected[field].as_str().unwrap_or("")){return Err("collector HMAC attestation mismatch".into())}}Ok(())}
pub fn verify_internal_digest(v:&Value,field:&str,exclude:&[&str])->Result<()>{let mut payload=v.clone();let object=payload.as_object_mut().ok_or("document must be object")?;object.remove(field);for f in exclude{object.remove(*f);}if v[field]!=digest(&payload){return Err(format!("{field} digest mismatch").into())}Ok(())}
#[cfg(test)]mod tests{use super::*;#[test]fn text_is_redacted_but_receipt_hash_is_raw(){let raw="bearer abcdefghijklmnop";let v=summarize(&[json!({"event_type":"text_delta","data":{"content":raw}})],"hash");assert_eq!(v["candidate_output"],"[REDACTED]");assert_eq!(v["text_events"][0]["content_sha256"],sha256(raw.as_bytes()));}#[test]fn collector_binding_rejects_mutation(){let key="x".repeat(32);let mut v=json!({"trials":[]});v["collector_attestation"]=attestation(&v,&key).unwrap();verify_attestation(&v,&key).unwrap();v["trials"]=json!([1]);assert!(verify_attestation(&v,&key).is_err());}}
